def clamp_sum(values, lo, hi):
    if lo > hi:
        raise ValueError("lo must be <= hi")
    total = 0
    if values is None:
        return total
    for value in values:
        if value is None:
            continue
        if value < lo:
            total += lo
        elif value > hi:
            total += hi
        else:
            total += value
    return total
